        sse_encode_i_32(17, serializer);
        sse_encode_String(name, serializer);
      case DaemonCommand_StartDiscovery():
        sse_encode_i_32(18, serializer);
      case DaemonCommand_GenerateCode():
        sse_encode_i_32(19, serializer);
      case DaemonCommand_ConnectPeer(
        peerId: final peerId,
        address: final address,
        port: final port,
        encryptionKey: final encryptionKey,
      ):
        sse_encode_i_32(20, serializer);
        sse_encode_String(peerId, serializer);
        sse_encode_String(address, serializer);
        sse_encode_u_16(port, serializer);
        sse_encode_opt_String(encryptionKey, serializer);
      case DaemonCommand_SendMessage(peerId: final peerId, text: final text):
        sse_encode_i_32(21, serializer);
        sse_encode_String(peerId, serializer);
        sse_encode_String(text, serializer);
      case DaemonCommand_StopDiscovery():
        sse_encode_i_32(22, serializer);
      case DaemonCommand_DisconnectPeer(peerId: final peerId):
        sse_encode_i_32(23, serializer);
        sse_encode_String(peerId, serializer);
    }
  }

  @protected
  void sse_encode_daemon_event(DaemonEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case DaemonEvent_PeerDiscovered(
        peerId: final peerId,
        name: final name,
        ip: final ip,
        port: final port,
      ):
        sse_encode_i_32(0, serializer);
        sse_encode_String(peerId, serializer);
        sse_encode_String(name, serializer);
        sse_encode_String(ip, serializer);
        sse_encode_u_16(port, serializer);
      case DaemonEvent_PeerLost(peerId: final peerId):
        sse_encode_i_32(1, serializer);
        sse_encode_String(peerId, serializer);
      case DaemonEvent_TransferProgress(
        transferId: final transferId,
        bytesTransferred: final bytesTransferred,
        totalBytes: final totalBytes,
        speed: final speed,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_String(transferId, serializer);
        sse_encode_u_64(bytesTransferred, serializer);
        sse_encode_u_64(totalBytes, serializer);
        sse_encode_f_64(speed, serializer);
      case DaemonEvent_TransferComplete(
        transferId: final transferId,
        status: final status,
      ):
        sse_encode_i_32(3, serializer);
        sse_encode_String(transferId, serializer);
        sse_encode_String(status, serializer);
      case DaemonEvent_PairingRequest(peerId: final peerId, pin: final pin):
        sse_encode_i_32(4, serializer);
        sse_encode_String(peerId, serializer);
        sse_encode_String(pin, serializer);
      case DaemonEvent_TransferOffer(
        peerId: final peerId,
        transferId: final transferId,
        fileName: final fileName,
        fileSize: final fileSize,
        thumbnail: final thumbnail,
      ):
        sse_encode_i_32(5, serializer);
        sse_encode_String(peerId, serializer);
        sse_encode_String(transferId, serializer);
        sse_encode_String(fileName, serializer);
        sse_encode_u_64(fileSize, serializer);
        sse_encode_opt_String(thumbnail, serializer);
      case DaemonEvent_LogMessage(level: final level, message: final message):
        sse_encode_i_32(6, serializer);
        sse_encode_String(level, serializer);
        sse_encode_String(message, serializer);
      case DaemonEvent_CredentialsGenerated(
        pin: final pin,
        sessionKey: final sessionKey,
      ):
        sse_encode_i_32(7, serializer);
        sse_encode_String(pin, serializer);
        sse_encode_String(sessionKey, serializer);
      case DaemonEvent_QrPayloadGenerated(payloadJson: final payloadJson):
        sse_encode_i_32(8, serializer);
        sse_encode_String(payloadJson, serializer);
      case DaemonEvent_SettingReported(key: final key, value: final value):
        sse_encode_i_32(9, serializer);
        sse_encode_String(key, serializer);
        sse_encode_String(value, serializer);
      case DaemonEvent_SessionCodeGenerated(code: final code):
        sse_encode_i_32(10, serializer);
        sse_encode_String(code, serializer);
      case DaemonEvent_SignalingStarted(id: final id):
        sse_encode_i_32(11, serializer);
        sse_encode_String(id, serializer);
      case DaemonEvent_CodeGenerated(
        key: final key,
        pin: final pin,
        ip: final ip,
      ):
        sse_encode_i_32(12, serializer);
        sse_encode_String(key, serializer);
        sse_encode_opt_String(pin, serializer);
        sse_encode_String(ip, serializer);
      case DaemonEvent_PeerDisconnected(peerId: final peerId):
        sse_encode_i_32(13, serializer);
        sse_encode_String(peerId, serializer);
      case DaemonEvent_PeerConnected(
        peerId: final peerId,
        name: final name,
        address: final address,
        port: final port,
      ):
        sse_encode_i_32(14, serializer);
        sse_encode_String(peerId, serializer);
        sse_encode_String(name, serializer);
        sse_encode_String(address, serializer);
        sse_encode_u_16(port, serializer);
    }
  }

  @protected
  void sse_encode_f_64(double self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putFloat64(self);
  }

  @protected
  void sse_encode_i_32(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putInt32(self);
  }

  @protected
  void sse_encode_list_prim_u_8_strict(
    Uint8List self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.length, serializer);
    serializer.buffer.putUint8List(self);
  }

  @protected
  void sse_encode_opt_String(String? self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs

    sse_encode_bool(self != null, serializer);
    if (self != null) {
      sse_encode_String(self, serializer);
    }
  }

  @protected
  void sse_encode_u_16(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint16(self);
  }

  @protected
  void sse_encode_u_64(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }

  @protected
  void sse_encode_u_8(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint8(self);
  }

  @protected
  void sse_encode_unit(void self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
  }

  @protected
  void sse_encode_bool(bool self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint8(self ? 1 : 0);
  }
}
